const x = $json;
if (!x.recordId || !x.claimantName || !x.parcelId) throw new Error('recordId, claimantName and parcelId are required');
return [{json:{...x, providerAllowed:x.providerAllowed === true, outreachDecision:'BLOCKED'}}];

const input = $json;
const results = Array.isArray(input.results) ? input.results : [input];
return results.map((r, i) => ({json:{recordId:input.recordId, parcelId:input.parcelId, candidateId:r.candidateId || `${input.recordId}:candidate:${i}`, name:r.name || null, addresses:r.addresses || (r.currentAddress ? [r.currentAddress] : []), phones:r.phones || [], emails:r.emails || [], profileUrl:r.profileUrl || null, source:r.source || 'authorized_skip_trace_provider', observedAt:new Date().toISOString(), ownershipStatus:'UNCONFIRMED', outreachStatus:'NOT_AUTHORIZED'}}));
